// Re-join the dataset row with S1's result so the item entering the AI node
// carries everything the evaluation panel needs (inputs + expected values).
const row = $('When fetching a dataset row').first().json;
const s1 = $('Laya Decide (S1)').first().json;
const a = s1.answers ?? {};
const team = a.team?.choice ?? '';
const conf = a.team?.confidence ?? null;
const urg = a.urgent?.noul ?? null;
// Routing rule mirrored from the demo workflows' Route Decision node:
//   confidence < 0.6 -> human_review; urgent >= 0.7 -> page_oncall:<team>; else queue:<team>
const route = (!team || conf === null) ? 'no_answer' : (conf < 0.6 ? 'human_review' : (urg >= 0.7 ? 'page_oncall:' + team : 'queue:' + team));
return [{ json: {
  ticket: String(row.ticket ?? ''),
  expected_team: String(row.expected_team ?? ''),
  expected_urgent: String(row.expected_urgent ?? ''),
  expected_route: String(row.expected_route ?? ''),
  model: String($('S2 Config').first().json.model ?? ''),
  s1_team: team,
  s1_route: route,
  s1_latency_ms: Math.round((s1.total_duration || 0) / 1e6)
} }];
